const dot = await Layer.layerCreatePrimitive('ellipse', 'Dot');
const dup = await Layer.layerCreate('duplicator', 'Radial');
await Gen.generatorSet(dup.layerId, 'circleDistribution', 'generator');
await Attr.attributeSetMany(dup.layerId, { 'generator.count': 16, 'generator.radius': 175 });
await Graph.graphConnect({ sourceLayerId: dot.layerId, sourceAttr: 'id', targetLayerId: dup.layerId, targetAttr: 'shapes', force: true });
